using Cosmos.Kernel.System.Graphics;
using Cosmos.Kernel.System.Graphics.Fonts;
using System;
using System.Drawing;

namespace Shinx.GUI
{
    public static class ASC16
    {
        private static PCScreenFont _font;
        private static bool _loaded;

        private static string PSF1 = "";

        public static void DrawACSIIString(Canvas vbe, string s, Color color, uint x, uint y)
        {
            if (string.IsNullOrEmpty(s)) return;
            if (!_loaded)
            {
                try { _font = PCScreenFont.LoadFont(Convert.FromBase64String(PSF1)); } catch { }
                _loaded = true;
            }
            if (_font != null)
                vbe.DrawString(s, _font, color, (int)x, (int)y);
        }
    }
}
